begin;
create table public.blocked_times(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),employee_id uuid,start_at timestamptz not null,end_at timestamptz not null,reason text not null,created_by uuid not null,created_at timestamptz not null default now(),check(end_at>start_at),constraint blocked_employee_company_fkey foreign key(employee_id,company_id) references public.profiles(id,company_id),constraint blocked_creator_company_fkey foreign key(created_by,company_id) references public.profiles(id,company_id));
create index blocked_company_period_idx on public.blocked_times(company_id,start_at,end_at);create index blocked_employee_company_idx on public.blocked_times(employee_id,company_id);create index blocked_creator_company_idx on public.blocked_times(created_by,company_id);
alter table public.blocked_times enable row level security;
create policy blocked_select on public.blocked_times for select to authenticated using(private.is_company_member(company_id));
create policy blocked_insert on public.blocked_times for insert to authenticated with check(private.has_company_role(company_id,array['proprietario','administrador','gerente','atendente']));
create policy blocked_update on public.blocked_times for update to authenticated using(private.has_company_role(company_id,array['proprietario','administrador','gerente','atendente'])) with check(private.has_company_role(company_id,array['proprietario','administrador','gerente','atendente']));
create policy blocked_delete on public.blocked_times for delete to authenticated using(private.has_company_role(company_id,array['proprietario','administrador','gerente','atendente']));
grant select,insert,update,delete on public.blocked_times to authenticated;revoke all on public.blocked_times from anon;
create function private.validate_appointment_slot() returns trigger language plpgsql set search_path='' as $$ declare v_company public.companies;v_count integer;begin if new.status in('cancelado','faltou') then return new;end if;select * into v_company from public.companies where id=new.company_id;if (new.scheduled_at at time zone 'America/Sao_Paulo')::time<v_company.opening_time or (new.scheduled_at at time zone 'America/Sao_Paulo')::time>=v_company.closing_time then raise exception 'Horário fora do funcionamento do PetShop';end if;if exists(select 1 from public.blocked_times b where b.company_id=new.company_id and (b.employee_id is null or b.employee_id=new.employee_id) and new.scheduled_at<b.end_at and new.scheduled_at+make_interval(mins=>new.estimated_duration_minutes)>b.start_at) then raise exception 'Horário bloqueado';end if;select count(*) into v_count from public.appointments a where a.company_id=new.company_id and a.id<>new.id and a.status not in('cancelado','faltou') and a.scheduled_at=new.scheduled_at;if v_count>=v_company.capacity_per_slot then raise exception 'Capacidade máxima atingida neste horário';end if;return new;end;$$;
revoke all on function private.validate_appointment_slot() from public,anon,authenticated;create trigger appointments_validate_slot before insert or update of scheduled_at,estimated_duration_minutes,status,employee_id on public.appointments for each row execute function private.validate_appointment_slot();
commit;
